import sqlite3

@route('/report')
def generate_report():
    start_date = request.query.start
    end_date = request.query.end
    db = sqlite3.connect('sales.db')
    sql = f"SELECT SUM(amount) FROM transactions WHERE date BETWEEN '{start_date}' AND '{end_date}'"
    result = db.execute(sql).fetchone()
    return {'total': result[0]}

